#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: set up the production server for Wordwright (#17, #349).
# Run it on your own computer, from anywhere: it connects to the server with ssh. The machine steps run from
# deploy/server-setup.sh on the server (read it first if you like); the wizard is for what only you can do:
# your keyboard, your browser, your accounts. Passwords and tokens go from your keyboard to the server and are never
# written on this computer; the only file this wizard keeps here holds the non-secret answers (ENV_FILE below).
# ──────────────────────────────────────────────────────────────────────────

DEPLOY_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="${ENV_FILE:-$DEPLOY_DIR/.env.server-setup}" # ignored by git (.env.*); answers that are not secret
APP_USER="wordwright"
SITE="app.wordwright.io"
REMOTE_DIR="wordwright" # under the app user's home

# One ssh connection per account is kept open for ten minutes (a private socket folder), so a passphrase is asked
# once, not on every command. The server's host key is checked against ~/.ssh/known_hosts, where stage 1 puts it
# after you have compared its fingerprint (StrictHostKeyChecking=yes: no trust-on-first-use).
CTL_DIR=$(mktemp -d /tmp/wwXXXXXX)
_close_connections() {
  local s
  for s in "$CTL_DIR"/*; do [[ -S "$s" ]] && ssh -o "ControlPath=$s" -O exit wordwright-setup >/dev/null 2>&1; done
  rm -rf "$CTL_DIR"
  return 0
}
trap _close_connections EXIT
_sshopts() {
  SSHO=(-i "$SSH_KEY" -o IdentitiesOnly=yes -o StrictHostKeyChecking=yes -o ControlMaster=auto -o ControlPersist=10m
    -o "ControlPath=${1:-$CTL_DIR/%C}")
}
ssh_root() { _sshopts; ssh "${SSHO[@]}" "root@$SERVER_IP" "$@"; }
ssh_app() { _sshopts; ssh "${SSHO[@]}" "$APP_USER@$SERVER_IP" "$@"; }
ssh_root_tty() { _sshopts; ssh -t "${SSHO[@]}" "root@$SERVER_IP" "$@"; }
ssh_app_tty() { _sshopts; ssh -t "${SSHO[@]}" "$APP_USER@$SERVER_IP" "$@"; }
# A brand-new login, not the open connection: proves that a fresh login still works.
ssh_app_fresh() { _sshopts none; ssh "${SSHO[@]}" "$APP_USER@$SERVER_IP" "$@"; }
scp_app() { _sshopts; scp "${SSHO[@]}" "$@"; }

# Reads KEY=value lines on stdin and sets each in the server's .env (replacing an earlier line for the same key).
# The values travel over ssh and are not shown or stored here.
remote_env_set() {
  ssh_app "cd $REMOTE_DIR && umask 077 && { [ -f .env ] || cp production.env.example .env; } && chmod 600 .env &&
    while IFS= read -r line; do
      key=\${line%%=*}
      grep -v \"^\${key}=\" .env > .env.tmp || true
      printf '%s\n' \"\$line\" >> .env.tmp
      mv .env.tmp .env
    done"
}
remote_env_has() { ssh_app "grep -q '^$1=.' $REMOTE_DIR/.env 2>/dev/null"; }

run_wizard() {

TOTAL_STAGES=12

banner "Wordwright: set up the production server"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Your computer, the server and the domain"
say "The wizard needs a few tools here, your SSH key, and the server's address."
for tool in ssh scp ssh-keyscan ssh-keygen rsync curl node gh git openssl; do
  if command -v "$tool" >/dev/null 2>&1; then say "✓ $tool"; else warn "$tool is missing: install it, then run the wizard again"; exit 1; fi
done
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in: run 'gh auth login' first"; exit 1; }
printf '\n'
ask SERVER_IP "Server's public IPv4 address:"
[[ "$SERVER_IP" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ ]] || { warn "'$SERVER_IP' is not an IPv4 address like 203.0.113.7"; exit 1; }
ask SSH_KEY "Path to your SSH private key (the one whose public half you gave UpCloud):"
SSH_KEY="${SSH_KEY/#\~/$HOME}"
[[ -f "$SSH_KEY" ]] || { warn "no key at $SSH_KEY"; exit 1; }
write_env SERVER_IP "$SERVER_IP"
write_env SSH_KEY "$SSH_KEY"
if ! ssh-keygen -F "$SERVER_IP" >/dev/null 2>&1; then
  scanned=$(ssh-keyscan -t ed25519 "$SERVER_IP" 2>/dev/null || true)
  [[ -n "$scanned" ]] || { warn "couldn't reach $SERVER_IP on port 22. Is the server running?"; exit 1; }
  say "This computer has not met the server before. Check that you are talking to the real one:"
  say "$(printf '%s\n' "$scanned" | ssh-keygen -lf -)"
  step "In UpCloud's web console for the server, log in and run:  ssh-keygen -lf /etc/ssh/ssh_host_ed25519_key.pub"
  confirm "Is the fingerprint the same?" || exit 1
  mkdir -p ~/.ssh && printf '%s\n' "$scanned" >> ~/.ssh/known_hosts
fi
found=$( (dig +short A "$SITE" 2>/dev/null || host "$SITE" 2>/dev/null) | grep -Eo '[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+' | head -n1 || true)
if [[ "$found" == "$SERVER_IP" ]]; then say "✓ $SITE points at $SERVER_IP"
else warn "$SITE points at '${found:-nothing yet}', not $SERVER_IP. Fix the A record in Gandi (a new one can take a few minutes)."; confirm "Carry on anyway?" || exit 1; fi
# The deploy files are copied from here but the images are built from main on GitHub, so the two must agree.
git -C "$DEPLOY_DIR" fetch origin main >/dev/null 2>&1 || warn "couldn't fetch origin/main; comparing with what this computer last saw"
if [[ -n "$(git -C "$DEPLOY_DIR" status --porcelain -- . 2>/dev/null)" ]]; then
  warn "deploy/ has uncommitted changes; the server would get them. Commit or discard them, then run the wizard again."; exit 1
fi
if [[ "$(git -C "$DEPLOY_DIR" rev-parse HEAD)" != "$(git -C "$DEPLOY_DIR" rev-parse origin/main 2>/dev/null || echo none)" ]]; then
  warn "This checkout is not at origin/main, but GitHub builds the images from main. Land your changes and check out main, then run the wizard again."; exit 1
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Base setup on the server"
note "You may be asked for your key's passphrase (once; the connection is kept open for a few minutes)."
# On a re-run, stage 3 may already have switched root login off, so ask the app's account first (#422).
if ssh_app "docker compose version" >/dev/null 2>&1; then
  say "✓ already done on an earlier run: you can log in as $APP_USER, and Docker works for it."
else
  say "This copies deploy/server-setup.sh to the server and runs it as root. It adds an account '$APP_USER'"
  say "for the app, installs Docker, switches the firewall on (SSH, 80, 443) and turns on automatic security updates."
  confirm "Run the base setup now?" || exit 1
  scp_app "$DEPLOY_DIR/server-setup.sh" "root@$SERVER_IP:/root/server-setup.sh"
  ssh_root_tty "APP_USER=$APP_USER bash /root/server-setup.sh base"
  say "Checking that you can log in as $APP_USER, and that Docker works for it:"
  ssh_app "docker --version && docker compose version"
  pause "All good? Press Enter."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Lock SSH down: no root login, no passwords"
if ssh_app "sudo sshd -T | grep -qx 'permitrootlogin no'"; then
  say "✓ already done on an earlier run: root cannot log in, and only key logins work."
else
  say "Only key logins stay possible, and only as $APP_USER. You just proved that login works, so this is safe;"
  say "it can still be undone from UpCloud's web console if something goes wrong."
  confirm "Switch off root login and passwords?" || exit 1
  ssh_app "sudo APP_USER=$APP_USER bash -s harden" < "$DEPLOY_DIR/server-setup.sh"
  setting=$(ssh_app "sudo sshd -T | grep -E '^(permitrootlogin|passwordauthentication) '")
  say "$setting"
  ssh_app_fresh true || { warn "a fresh login as $APP_USER failed. Use UpCloud's web console to undo it: delete /etc/ssh/sshd_config.d/00-wordwright.conf, then 'systemctl reload ssh'."; exit 1; }
  say "✓ a fresh login still works as $APP_USER"
  note "Optional: UpCloud's own firewall (server → Firewall in the control panel) can also allow only 22, 80 and 443."
  pause "Press Enter."
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Put the deploy files on the server"
ssh_app "mkdir -p $REMOTE_DIR"
scp_app "$DEPLOY_DIR/compose.yaml" "$DEPLOY_DIR/deploy.sh" "$DEPLOY_DIR/backup.sh" "$DEPLOY_DIR/rollback.sh" "$DEPLOY_DIR/production.env.example" \
  "$DEPLOY_DIR/server-setup.sh" "$APP_USER@$SERVER_IP:$REMOTE_DIR/"
ssh_app "chmod +x $REMOTE_DIR/*.sh"
ssh_app "ls -l $REMOTE_DIR"
pause "Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Build the images on GitHub"
say "GitHub builds the two images and stores them privately in its container registry. It takes a few minutes."
IMAGE_TAG=$(_existing IMAGE_TAG || true)
if [[ -n "$IMAGE_TAG" ]] && ! confirm "Images for $IMAGE_TAG were built on an earlier run. Build new ones from main?"; then
  say "Keeping $IMAGE_TAG."
else
  confirm "Run the 'Images' workflow on main now?" || exit 1
  latest_run() { gh run list --workflow image.yml --event workflow_dispatch --branch main --limit 1 --json databaseId -q '.[0].databaseId // 0'; }
  before=$(latest_run)
  gh workflow run image.yml --ref main
  run_id=$before
  for _ in $(seq 1 30); do # GitHub takes a few seconds to list the new run; never pick up the previous one
    run_id=$(latest_run)
    [[ "$run_id" != "$before" ]] && break
    sleep 2
  done
  [[ "$run_id" != "$before" ]] || { warn "GitHub did not start a new run. Look at the Actions tab, then run the wizard again."; exit 1; }
  say "Watching run $run_id (Ctrl-C stops watching, not the build):"
  gh run watch "$run_id" --exit-status
  IMAGE_TAG=$(gh run view "$run_id" --json headSha -q .headSha)
  write_env IMAGE_TAG "$IMAGE_TAG"
  say "✓ built commit $IMAGE_TAG"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Let the server pull the private images"
say "The server needs a token that can only READ packages. It is typed to the server, not saved here."
if ssh_app "grep -q ghcr.io ~/.docker/config.json 2>/dev/null" && ! confirm "The server is already logged in to ghcr.io. Log in again with a new token?"; then
  say "Keeping the existing login."
else
  open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=wordwright-server"
  step "Name it 'wordwright-server', set an expiry you will remember (a year), and keep only read:packages ticked."
  step "Click Generate token, then copy it (it starts ghp_)."
  ask GITHUB_USER "Your GitHub username:"
  [[ "$GITHUB_USER" =~ ^[A-Za-z0-9-]+$ ]] || { warn "'$GITHUB_USER' is not a GitHub username"; exit 1; }
  write_env GITHUB_USER "$GITHUB_USER"
  ask_secret GHCR_TOKEN "Paste the token (hidden):"
  printf '%s' "$GHCR_TOKEN" | ssh_app "docker login ghcr.io -u '$GITHUB_USER' --password-stdin"
  unset GHCR_TOKEN
  warn "This token can read every package your account can see, and the server keeps it. Revoke it if the server is ever compromised."
  SKIPPED+=("The GitHub token for the server expires on the date you chose: make a new one then (re-run the wizard to Log in again), or deploys will stop pulling")
fi
say "Trying to pull the API image:"
ssh_app "docker pull ghcr.io/jenit/wordwright-api:$IMAGE_TAG >/dev/null && echo '✓ pulled'"
pause "Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Secrets the app encrypts with"
if remote_env_has KEY_ENCRYPTION_SECRET; then
  say "The server already has its secrets, so they are kept. Making new ones would make every saved AI key unreadable."
else
  say "Two random secrets are made here and sent to the server. One of them must ALSO be kept safe by you."
  SESSION_SECRET=$(openssl rand -base64 48 | tr -d '\n')
  KEY_ENCRYPTION_SECRET=$(openssl rand -base64 48 | tr -d '\n')
  printf '\n'
  warn "Rebuilding a server to restore its backups? Do NOT save this over your old one: keep the old one, and after this"
  warn "wizard put it on the server with deploy/restore-key-secret.sh (docs/deploy.md). Otherwise:"
  warn "Save this in your password manager now, named 'Wordwright KEY_ENCRYPTION_SECRET'."
  say "Without it, a restored backup holds AI keys nobody can read, and every writer must enter theirs again:"
  printf '\n    %s%s%s\n\n' "$BOLD" "$KEY_ENCRYPTION_SECRET" "$RESET"
  until confirm "Saved in your password manager?"; do say "Please save it first; it is not stored anywhere else."; done
  # Take the secret off the screen, and out of the terminal's scrollback.
  [[ -t 1 ]] && printf '\033[2J\033[3J\033[H'
  printf 'SESSION_SECRET=%s\nKEY_ENCRYPTION_SECRET=%s\n' "$SESSION_SECRET" "$KEY_ENCRYPTION_SECRET" | remote_env_set
  unset SESSION_SECRET KEY_ENCRYPTION_SECRET
  say "✓ sent to the server"
fi
pause "Press Enter."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Email: Scaleway's SMTP details"
say "Scaleway sends the app's email (confirmations, resets, invitations). Its SMTP address contains a password."
say "First, can the server reach Scaleway's mail server? (UpCloud blocks outgoing mail ports on trial accounts, and its"
say "firewall can block them too; this took an afternoon to find the first time.)"
if ssh_app "timeout 8 bash -c '</dev/tcp/smtp.tem.scaleway.com/465'" 2>/dev/null; then
  say "✓ the server can reach smtp.tem.scaleway.com on port 465"
else
  warn "The server cannot reach smtp.tem.scaleway.com on port 465, so no email would be sent."
  say "In UpCloud: trial accounts cannot edit the firewall until a payment is made. Then check the server's Firewall tab:"
  say "outgoing connections must be allowed (see 'The firewall' in docs/deploy.md)."
  confirm "Carry on anyway (you can fix this and run the wizard again later)?" || exit 1
fi
open_url "https://console.scaleway.com/transactional-email/domains"
step "Open your domain, then find the SMTP settings or credentials (a section called 'SMTP' or 'API keys and SMTP')."
step "If there is no SMTP credential yet, create one (an API key is used as the SMTP password)."
note "Scaleway's console may change; the host is likely smtp.tem.scaleway.com and the port 465 or 587. Use what the console shows."
ask SCW_SMTP_HOST "SMTP host:"
ask SCW_SMTP_PORT "SMTP port (465 is the simple one; use it if offered):"
note "The username is your Scaleway PROJECT ID (Domain overview), not an email address or an API access key."
ask SCW_SMTP_USER "SMTP username (the Project ID):"
[[ "$SCW_SMTP_PORT" =~ ^[0-9]{2,5}$ ]] || { warn "'$SCW_SMTP_PORT' is not a port number"; exit 1; }
write_env SCW_SMTP_HOST "$SCW_SMTP_HOST"
write_env SCW_SMTP_PORT "$SCW_SMTP_PORT"
write_env SCW_SMTP_USER "$SCW_SMTP_USER"
note "The password is the SECRET key of an API key that has Transactional Email permissions in that same project."
if remote_env_has SMTP_URL; then
  ask_secret SCW_SMTP_PASSWORD "SMTP password (the secret key; hidden; Enter keeps what the server has):"
else
  ask_secret SCW_SMTP_PASSWORD "SMTP password (the secret key; hidden):"
  # A new server has nothing to keep, and the app will not start without it (#422).
  until [[ -n "$SCW_SMTP_PASSWORD" ]]; do
    warn "The server has no SMTP settings yet, and the app will not start without them. Paste the secret key."
    ask_secret SCW_SMTP_PASSWORD "SMTP password (the secret key; hidden):"
  done
fi
if [[ -n "$SCW_SMTP_PASSWORD" ]]; then
  enc() { node -e 'process.stdout.write(encodeURIComponent(process.argv[1]))' "$1"; }
  scheme="smtps"; suffix=""
  if [[ "$SCW_SMTP_PORT" != "465" ]]; then scheme="smtp"; suffix="?requireTLS=true"; warn "Port $SCW_SMTP_PORT: the app will insist on TLS (STARTTLS)."; fi
  printf 'MAIL_TRANSPORT=smtp\nMAIL_FROM=Wordwright <hello@wordwright.io>\nSMTP_URL=%s://%s:%s@%s:%s%s\n' \
    "$scheme" "$(enc "$SCW_SMTP_USER")" "$(enc "$SCW_SMTP_PASSWORD")" "$SCW_SMTP_HOST" "$SCW_SMTP_PORT" "$suffix" | remote_env_set
  unset SCW_SMTP_PASSWORD
  say "✓ sent to the server"
else say "Kept the SMTP settings already on the server."; fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Google sign-in (optional)"
say "Without it people sign in with email and a password only. Set it up in Google Cloud first (docs/deploy.md, 'Google sign-in')."
if remote_env_has GOOGLE_CLIENT_SECRET && ! confirm "The server already has Google sign-in settings. Replace them?"; then
  say "Kept the Google settings already on the server."
elif confirm "Enter the Google client ID and secret now?"; then
  note "The redirect URI registered with Google must be exactly: https://$SITE/api/auth/oauth/google/callback"
  ask GOOGLE_CLIENT_ID "Client ID (ends .apps.googleusercontent.com):"
  [[ "$GOOGLE_CLIENT_ID" == *.apps.googleusercontent.com ]] || warn "That does not look like a Google client ID; check it if sign-in fails."
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  ask_secret GOOGLE_CLIENT_SECRET "Client secret (hidden):"
  if [[ -n "$GOOGLE_CLIENT_ID" && -n "$GOOGLE_CLIENT_SECRET" ]]; then
    printf 'GOOGLE_CLIENT_ID=%s\nGOOGLE_CLIENT_SECRET=%s\n' "$GOOGLE_CLIENT_ID" "$GOOGLE_CLIENT_SECRET" | remote_env_set
    unset GOOGLE_CLIENT_SECRET
    say "✓ sent to the server"
    SKIPPED+=("Google sign-in: add each alpha writer's Google address as a test user while the app is in Testing (docs/deploy.md), then try it (issue #350)")
  else
    unset GOOGLE_CLIENT_SECRET
    warn "Both are needed, so nothing was sent. Run the wizard again to retry."
    SKIPPED+=("Google sign-in is off until both the ID and the secret are entered (issue #350)")
  fi
else
  SKIPPED+=("Google sign-in is off until it is set up (issue #350); run the wizard again to enter it")
fi
pause "Press Enter."

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "First deploy"
say "This writes the address settings, then pulls the images and starts the app."
printf 'SITE_ADDRESS=%s\nPUBLIC_URL=https://%s\nNODE_ENV=production\nWORDWRIGHT_TAG=%s\n' \
  "$SITE" "$SITE" "$IMAGE_TAG" | remote_env_set
confirm "Start the app now?" || exit 1
ssh_app_tty "cd $REMOTE_DIR && ./deploy.sh"
sleep 5
say "Asking the public address (the certificate can take a minute the first time):"
for _ in $(seq 1 12); do
  if body=$(curl -fsS --max-time 10 "https://$SITE/health" 2>/dev/null); then say "✓ $body"; break; fi
  sleep 5
done
[[ -n "${body:-}" ]] || { warn "https://$SITE/health did not answer. On the server: docker compose logs --tail 100 (in ~/$REMOTE_DIR)"; exit 1; }
if ssh_app "cd $REMOTE_DIR && docker compose logs --tail 200 api 2>&1 | grep -q 'SMTP connection verified'"; then
  say "✓ the app reached Scaleway and its SMTP login was accepted"
else
  warn "The app did not report a working SMTP connection. See 'If email does not send' in docs/deploy.md; to look:"
  say "  ssh $APP_USER@$SERVER_IP 'cd $REMOTE_DIR && docker compose logs --tail 50 api | grep -i email'"
  SKIPPED+=("Email: the app could not verify its SMTP connection (docs/deploy.md: 'If email does not send')")
fi
open_url "https://$SITE"
pause "Do you see the Wordwright sign-in page? Press Enter."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Check the email really arrives"
warn "Anyone who knows the address can create an account until the alpha approval feature (#328) is built. Don't share it yet."
open_url "https://$SITE"
step "Create an account with your Gmail address. The confirmation email should arrive within a minute, not in spam."
step "In Gmail: ⋮ → Show original. SPF, DKIM and DMARC should all say PASS, and it should come from hello@wordwright.io."
step "Repeat with an Outlook (or Hotmail) address and an iCloud address if you have them, and try 'Forgot password' once."
step "Note the results in https://github.com/JeniT/wordwright/issues/349 (arrived? spam? PASS?)."
if ! confirm "Did the email arrive, in the inbox, with all three passing?"; then
  SKIPPED+=("Email deliverability: fix and re-test (issue #349). Scaleway's logs show what was sent.")
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Nightly backups, and a copy on this computer"
say "A timer on the server backs up the database at 02:30 every night and keeps 14 days."
confirm "Install the timer and take a first backup now?" || exit 1
ssh_app "sudo APP_USER=$APP_USER bash $REMOTE_DIR/server-setup.sh timer"
ssh_app "cd $REMOTE_DIR && ./backup.sh"
ask LOCAL_BACKUP_DIR "Where on this computer should copies go?"
LOCAL_BACKUP_DIR="${LOCAL_BACKUP_DIR/#\~/$HOME}"
write_env LOCAL_BACKUP_DIR "$LOCAL_BACKUP_DIR"
mkdir -p "$LOCAL_BACKUP_DIR"
chmod 700 "$LOCAL_BACKUP_DIR"
warn "These copies hold every writer's data, including their encrypted AI keys. Keep the folder on an encrypted disk (FileVault), and delete old copies, which the server does after 14 days."
rsync -a -e "ssh -i \"$SSH_KEY\" -o IdentitiesOnly=yes -o ControlPath=$CTL_DIR/%C" "$APP_USER@$SERVER_IP:backups/" "$LOCAL_BACKUP_DIR/"
ls -l "$LOCAL_BACKUP_DIR"
printf -v fetch_cmd 'rsync -a -e "ssh -i %q" %s@%s:backups/ %q/' "$SSH_KEY" "$APP_USER" "$SERVER_IP" "$LOCAL_BACKUP_DIR"
SKIPPED+=("Fetch backups regularly: $fetch_cmd   (until a proper off-site copy is set up, issue #17)")

finish
}

run_wizard "$@"; exit
